mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin\r\n\r\n@mixin margin(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center($vertical: null) {\r\n  @include margin($x: auto, $y: $vertical);\r\n}\r\n\r\n@mixin margin-middle($horizontal: null) {\r\n  @include margin($x: $horizontal, $y: auto);\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-square($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin($all: auto);\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin($all: 0);\r\n}\r\n\r\n// padding\r\n\r\n@mixin padding(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: padding,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin padding-xy($x: null, $y: null) {\r\n  @include padding($x: $x, $y: $y);\r\n}\r\n\r\n@mixin padding-axis($horizontal: null, $vertical: null) {\r\n  @include padding($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin padding-all($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-square($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-none {\r\n  @include padding($all: 0);\r\n}\r\n","////\r\n/// @group transition\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:list';\r\n@use 'sass:meta';\r\n@use 'config/animations';\r\n\r\n@mixin apply($props...) {\r\n  $transitions: ();\r\n\r\n  @for $i from 1 through list.length($props) {\r\n    $prop: list.nth($props, $i);\r\n\r\n    $name: $prop;\r\n    $duration: animations.$transition-duration;\r\n    $function: animations.$transition-function;\r\n\r\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\r\n      $name: list.nth($prop, 1);\r\n\r\n      @if list.nth($prop, 2) {\r\n        $duration: list.nth($prop, 2);\r\n      }\r\n\r\n      @if list.length($prop) > 2 and list.nth($prop, 3) {\r\n        $function: list.nth($prop, 3);\r\n      }\r\n    }\r\n\r\n    $transitions: list.append($transitions, '#{$name} #{$duration} #{$function}');\r\n  }\r\n\r\n  @if list.length($transitions) > 0 {\r\n    transition: #{list.zip($transitions)};\r\n  }\r\n}\r\n","////\r\n/// @group aria\r\n/// @access public\r\n/// @author Keith Choison <keith@tize.io>\r\n////\r\n\r\n@use 'sass:math';\r\n@use 'config/colors';\r\n@use 'functions/color';\r\n@use 'position';\r\n@use 'transition';\r\n\r\n///\r\n/// Includes styling for a pseudo-element that displays an outline primarily for accessibility purposes.\r\n/// Requires at least one unusued pseudo-element (i.e, `::before` or `::after`) in the element this mixin is applied to.\r\n///\r\n/// @param {string} $position [relative] - Position of the outline. Specifying `null` will output no `position` property.\r\n/// @param {string} $pseudo [after] - Pseudo-element to use for displaying the outline. Can be `before` or `after`.\r\n/// @param {number} $offset [0] - Spacing between the container and the outline. Works just like the CSS `outline-offset` property.\r\n/// @param {number} $width [2px] - Width (thickness) of the outline. Works just like the CSS `outline-width` and `border-width` properties.\r\n/// @param {string} $style [solid] - Line style of the outline. Works just like the CSS `outline-style` and `border-style` properties.\r\n/// @param {string} $color [colors.$blue] - Color of the outline. Works just like the CSS `outline-color` and `border-color` properties.\r\n/// @param {number} $radius - Optional border radius of the outline. Works just like the CSS `border-radius` property.\r\n/// @param {number} $opacity [0] - Initial opacity of the outline. Set to `null` to not use opacity as the transition property (`border-color` will be used instead).\r\n/// @param {number} $z-index - Optional z-index value of the pseudo-element.\r\n///\r\n@mixin outline(\r\n  $position: relative,\r\n  $pseudo: after,\r\n  $offset: 4px,\r\n  $width: 2px,\r\n  $style: solid,\r\n  $color: colors.$blue,\r\n  $radius: null,\r\n  $opacity: 0,\r\n  $z-index: null,\r\n) {\r\n  @if $position {\r\n    position: $position;\r\n  }\r\n\r\n  outline: none;\r\n\r\n  &::#{$pseudo} {\r\n    content: '';\r\n    @include position.absolute($all: -$offset);\r\n    border: $width $style $color;\r\n    opacity: $opacity;\r\n    @include transition.apply(border-color, opacity);\r\n    pointer-events: none;\r\n\r\n    @if $radius {\r\n      @if math.abs($offset) > 0 {\r\n        $radius: $radius + math.abs($offset);\r\n      }\r\n\r\n      border-radius: $radius;\r\n    }\r\n\r\n    @if $z-index {\r\n      z-index: $z-index;\r\n    }\r\n\r\n    @content;\r\n  }\r\n}\r\n\r\n@mixin outline-hover(\r\n  $color: colors.$black,\r\n  $opacity: 0.08,\r\n) {\r\n  border-color: $color;\r\n  opacity: $opacity;\r\n\r\n  @content;\r\n}\r\n\r\n@mixin outline-show(\r\n  $color: colors.$blue,\r\n  $opacity: 0.88,\r\n  $duration: 256ms,\r\n  $timing: ease-out,\r\n) {\r\n  border-color: $color;\r\n  opacity: $opacity;\r\n  transform: scale(1);\r\n\r\n  @content;\r\n}\r\n","////\r\n/// @group position\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:meta';\r\n@use 'functions/list';\r\n\r\n@mixin -position(\r\n  $position: relative,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('absolute' 'fixed' 'relative', $position) {\r\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\r\n  }\r\n\r\n  position: $position;\r\n\r\n  @if $top {\r\n    top: $top;\r\n  }\r\n\r\n  @if $right {\r\n    right: $right;\r\n  }\r\n\r\n  @if $bottom {\r\n    bottom: $bottom;\r\n  }\r\n\r\n  @if $left {\r\n    left: $left;\r\n  }\r\n}\r\n\r\n// translate\r\n\r\n@mixin translate(\r\n  $x: null,\r\n  $y: null,\r\n) {\r\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\r\n    @if $x and $x != 0 and $y and $y != 0 {\r\n      transform: translate($x, $y);\r\n    } @else if $x and $x != 0 {\r\n      transform: translateX($x);\r\n    } @else if $y and $y != 0 {\r\n      transform: translateY($y);\r\n    }\r\n  }\r\n}\r\n\r\n// unset all\r\n\r\n@mixin unset-all {\r\n  top: unset;\r\n  right: unset;\r\n  bottom: unset;\r\n  left: unset;\r\n}\r\n\r\n// absolute\r\n\r\n@mixin absolute(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -position(\r\n    $position: absolute,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin absolute-xy($x: null, $y: null) {\r\n  @include absolute($x: $x, $y: $y);\r\n}\r\n\r\n@mixin absolute-axis($horizontal: null, $vertical: null) {\r\n  @include absolute($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin absolute-all($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n@mixin absolute-square($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n@mixin absolute-fill {\r\n  @include absolute($all: 0);\r\n}\r\n\r\n@mixin absolute-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  $translate-x: if($x, -$x, null);\r\n  $translate-y: if($y, -$y, null);\r\n\r\n  @if $translate-x and unit($translate-x) != '%' { // e.g., px\r\n    $translate-x: 0;\r\n  }\r\n\r\n  @if $translate-y and unit($translate-y) != '%' {\r\n    $translate-y: 0;\r\n  }\r\n\r\n  @include absolute(\r\n    $top: if($y-prop == top, $y, null),\r\n    $right: if($x-prop == right, $x, null),\r\n    $bottom: if($y-prop == bottom, $y, null),\r\n    $left: if($x-prop == left, $x, null),\r\n  );\r\n\r\n  @include translate($x: $translate-x, $y: $translate-y);\r\n}\r\n\r\n@mixin absolute-center($x-prop: left, $y-prop: top) {\r\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\r\n}\r\n\r\n// fixed\r\n\r\n@mixin fixed(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -position(\r\n    $position: fixed,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin fixed-xy($x: null, $y: null) {\r\n  @include fixed($x: $x, $y: $y);\r\n}\r\n\r\n@mixin fixed-axis($horizontal: null, $vertical: null) {\r\n  @include fixed($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin fixed-all($margin) {\r\n  @include fixed($all: $margin);\r\n}\r\n\r\n@mixin fixed-square($margin) {\r\n  @include fixed($all: $margin);\r\n}\r\n\r\n@mixin fixed-fill {\r\n  @include fixed($all: 0);\r\n}\r\n\r\n@mixin fixed-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  $translate-x: if($x, -$x, null);\r\n  $translate-y: if($y, -$y, null);\r\n\r\n  @if $translate-x and unit($translate-x) != '%' {\r\n    $translate-x: 0;\r\n  }\r\n\r\n  @if $translate-y and unit($translate-y) != '%' {\r\n    $translate-y: 0;\r\n  }\r\n\r\n  @include fixed(\r\n    $top: if($y-prop == top, $y, null),\r\n    $right: if($x-prop == right, $x, null),\r\n    $bottom: if($y-prop == bottom, $y, null),\r\n    $left: if($x-prop == left, $x, null),\r\n  );\r\n\r\n  @include translate($x: $translate-x, $y: $translate-y);\r\n}\r\n\r\n@mixin fixed-center($x-prop: left, $y-prop: top) {\r\n  @include fixed-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\r\n}\r\n","$black: #000000;\r\n$white: #FFFFFF;\r\n\r\n$gray-lighter: #EEEEEE; // MD Gray 200\r\n$gray-light: #BDBDBD; // MD Gray 400\r\n$gray: #9E9E9E; // MD Gray 500\r\n$gray-dark: #424242; // MD Gray 800\r\n$gray-darker: #212121; // MD Gray 900\r\n$gray-darkest: #121212;\r\n\r\n$red: #F44336; // MD Red 500\r\n$green: #4CAF50; // MD Green 500\r\n$blue: #2196F3; // MD Blue 500\r\n\r\n$pink: #E91E63; // MD Pink 500\r\n$orange: #FF9800; // MD Orange 500\r\n$cyan: #00ACC1; // MD Cyan 500\r\n\r\n$transparent-black: rgba(0, 0, 0, 0);\r\n$transparent-white: rgba(255, 255, 255, 0);\r\n$transparent: $transparent-white;\r\n\r\n$showdown-background-light: #EEF2F5;\r\n$showdown-background-dark: #444444;\r\n","////\r\n/// @group flex\r\n/// @author Keith Choison\r\n////\r\n\r\n@mixin -flex($direction: null, $justify: null, $align: null, $inline: false) {\r\n  display: if($inline, inline-flex, flex);\r\n\r\n  @if $direction and $direction != row {\r\n    flex-direction: $direction;\r\n  }\r\n\r\n  @if $justify and $justify != flex-start {\r\n    justify-content: $justify;\r\n  }\r\n\r\n  @if $align and $align != stretch {\r\n    align-items: $align;\r\n  }\r\n\r\n  // @if $inline {\r\n  //   vertical-align: middle;\r\n  // }\r\n}\r\n\r\n// rows\r\n\r\n@mixin row($justify: null, $align: null, $inline: false) {\r\n  @include -flex(row, $justify, $align, $inline);\r\n}\r\n\r\n@mixin row-start($inline: false) {\r\n  @include row(flex-start, center, $inline);\r\n}\r\n\r\n@mixin row-center($inline: false) {\r\n  @include row(center, center, $inline);\r\n}\r\n\r\n@mixin row-end($inline: false) {\r\n  @include row(flex-end, center, $inline);\r\n}\r\n\r\n@mixin row-between($inline: false) {\r\n  @include row(space-between, center, $inline);\r\n}\r\n\r\n@mixin row-around($inline: false) {\r\n  @include row(space-around, center, $inline);\r\n}\r\n\r\n// columns\r\n\r\n@mixin column($justify: null, $align: null, $inline: false) {\r\n  @include -flex(column, $justify, $align, $inline);\r\n}\r\n\r\n@mixin column-start($inline: false) {\r\n  @include column(flex-start, center, $inline);\r\n}\r\n\r\n@mixin column-center($inline: false) {\r\n  @include column(center, center, $inline);\r\n}\r\n\r\n@mixin column-end($inline: false) {\r\n  @include column(flex-end, center, $inline);\r\n}\r\n\r\n@mixin column-between($inline: false) {\r\n  @include column(space-between, center, $inline);\r\n}\r\n\r\n@mixin column-around($inline: false) {\r\n  @include column(space-around, center, $inline);\r\n}\r\n","////\r\n/// 