t of Hellodex footer\r\n  // backdrop-filter: blur(2px); // causes scrolling lag due to blurred pixel recalculations\r\n  @include transition.apply(color, background-color);\r\n  overflow: hidden;\r\n  z-index: 1;\r\n\r\n  &.light {\r\n    color: colors.$black;\r\n    background-color: color.alpha(colors.$white, 0.94);\r\n\r\n    &.mina {\r\n      background-color: color.alpha(#F5DAE3, 0.88);\r\n    }\r\n  }\r\n\r\n  &.dark {\r\n    color: colors.$white;\r\n    background-color: color.alpha(colors.$gray-darkest, 0.94);\r\n\r\n    &.mina {\r\n      background-color: color.alpha(#2D0D1C, 0.94);\r\n    }\r\n  }\r\n\r\n  &.glassy {\r\n    backdrop-filter: blur(4px);\r\n\r\n    &.light {\r\n      background-color: color.alpha(colors.$white, 0.64);\r\n\r\n      &.mina {\r\n        background-color: color.alpha(#F5DAE3, 0.64);\r\n      }\r\n    }\r\n\r\n    &.dark {\r\n      background-color: color.alpha(colors.$gray-darkest, 0.8);\r\n\r\n      &.mina {\r\n        background-color: color.alpha(#2D0D1C, 0.8);\r\n      }\r\n    }\r\n  }\r\n\r\n  code {\r\n    @include font.apply(fonts.$mono);\r\n  }\r\n}\r\n\r\n.contentContainer {\r\n  @include position.absolute-fill;\r\n  overflow-x: hidden;\r\n}\r\n\r\n.content {\r\n  @include spacing.padding($all: 16px);\r\n}\r\n\r\n.header {\r\n  @include flex.row-between;\r\n  @include spacing.padding($x: 12px, $top: 4px, $bottom: 6px);\r\n  @include transition.apply(padding);\r\n  user-select: none;\r\n\r\n  .inBattle & {\r\n    @include spacing.padding($x: 6px);\r\n  }\r\n\r\n  &:hover .settingsIcon {\r\n    transform: rotateZ(360deg);\r\n  }\r\n\r\n  .left {\r\n    @include flex.row-start;\r\n    opacity: 0.88;\r\n\r\n    .settingsIcon {\r\n      width: $settings-icon-size;\r\n      min-width: $settings-icon-size;\r\n      height: $settings-icon-size;\r\n      min-height: $settings-icon-size;\r\n      @include transition.apply((transform, 10s));\r\n    }\r\n\r\n    .title {\r\n      @include spacing.margin($left: 12px);\r\n      font-weight: 500;\r\n      font-size: 14px;\r\n      text-transform: uppercase;\r\n    }\r\n  }\r\n\r\n  .right {\r\n    @include flex.row-end;\r\n\r\n    .actionButton {\r\n      position: relative;\r\n      font-family: inherit;\r\n      font-weight: 500;\r\n      font-size: 10px;\r\n      color: inherit;\r\n      text-transform: uppercase;\r\n\r\n      &:not(.undoButton):hover {\r\n        .light & {\r\n          color: color.shade(colors.$blue, 15%);\r\n        }\r\n\r\n        .dark & {\r\n          color: colors.$blue;\r\n        }\r\n      }\r\n\r\n      &:not(:last-of-type) {\r\n        @include spacing.margin($right: 8px);\r\n      }\r\n\r\n      .inBattle &:not(:last-of-type) {\r\n        @include spacing.margin($right: 2px);\r\n      }\r\n\r\n      &:last-of-type {\r\n        @include spacing.margin($right: 16px);\r\n      }\r\n    }\r\n\r\n    .importButton {\r\n      &.undoButton {\r\n        .light & {\r\n          color: color.shade(colors.$red, 16%);\r\n        }\r\n\r\n        .dark & {\r\n          color: colors.$red;\r\n        }\r\n      }\r\n    }\r\n\r\n    .defaultsButton {\r\n      @include spacing.margin($right: 16px);\r\n\r\n      .inBattle & {\r\n        @include spacing.margin($right: 8px);\r\n      }\r\n    }\r\n  }\r\n}\r\n\r\n.importTooltip {\r\n  position: relative;\r\n\r\n  .importBadge {\r\n    @include position.absolute($top: -16px, $left: 50%);\r\n  }\r\n}\r\n\r\n.closePlaceholder {\r\n  width: $close-icon-size;\r\n  min-width: $close-icon-size;\r\n  height: 1px;\r\n  pointer-events: none;\r\n}\r\n\r\n.closeButton {\r\n  @include position.absolute($top: 24px, $right: 24px);\r\n  color: inherit;\r\n  z-index: 2;\r\n\r\n  .light & {\r\n    color: colors.$gray-dark;\r\n  }\r\n\r\n  .closeIcon {\r\n    width: $close-icon-size;\r\n    min-width: $close-icon-size;\r\n    height: $close-icon-size;\r\n    min-height: $close-icon-size;\r\n  }\r\n}\r\n\r\n.notice {\r\n  @include spacing.padding($x: 12px, $top: 12px);\r\n  font-size: 12px;\r\n  text-align: center;\r\n  opacity: 0.6;\r\n  user-select: none;\r\n\r\n  .face {\r\n    font-size: 16px;\r\n  }\r\n}\r\n\r\n.settingsGroup {\r\n  @include spacing.margin($y: 12px);\r\n  @include spacing.padding($x: 12px, $top: 20px, $bottom: 24px);\r\n  border-radius: 12px;\r\n  @include transition.apply(background-color, box-shadow);\r\n\r\n  .light & {\r\n    background-color: color.alpha(colors.$white, 0.8);\r\n    box-shadow: (\r\n      0 0 1px color.alpha(colors.$black, 0.16),\r\n      0 0 16px color.alpha(colors.$gray-dark, 0.16),\r\n    );\r\n  }\r\n\r\n  .light.mina & {\r\n    background-color: color.alpha(#FFF7FA, 0.8);\r\n    box-shadow: (\r\n      0 0 1px color.alpha(#770629, 0.32),\r\n      0 0 16px color.alpha(#9F1641, 0.16),\r\n    );\r\n  }\r\n\r\n  .dark & {\r\n    background-color: color.alpha(colors.$gray-darkest, 0.8);\r\n    box-shadow: (\r\n      0 0 1px color.alpha(colors.$white, 0.32),\r\n      0 0 8px color.alpha(colors.$gray-dark, 0.48),\r\n    );\r\n  }\r\n\r\n  .dark.mina & {\r\n    background-color: color.alpha(#100206, 0.48);\r\n  }\r\n\r\n  .glassy & {\r\n    backdrop-filter: blur(4px);\r\n  }\r\n\r\n  .glassy.light & {\r\n    background-color: color.alpha(colors.$white, 0.24);\r\n  }\r\n\r\n  .glassy.light.mina & {\r\n    background-color: color.alpha(#FFF7FA, 0.4);\r\n  }\r\n\r\n  .glassy.dark & {\r\n    background-color: color.alpha(colors.$black, 0.24);\r\n  }\r\n\r\n  .glassy.dark.mina & {\r\n    background-color: color.alpha(#100206, 0.24);\r\n  }\r\n}\r\n\r\n.settingsGroupTitle {\r\n  @include spacing.margin($bottom: 16px);\r\n  @include spacing.padding($x: 12px);\r\n  font-weight: 500;\r\n  font-size: 14px;\r\n  letter-spacing: 0.5px;\r\n  text-transform: uppercase;\r\n  @include transition.apply(color);\r\n  user-select: none;\r\n\r\n  .light & {\r\n    color: color.alpha(colors.$black, 0.84);\r\n  }\r\n\r\n  .dark & {\r\n    color: color.alpha(colors.$white, 0.84);\r\n  }\r\n}\r\n\r\n.settingsGroupFields {\r\n  display: grid;\r\n  grid-template-columns: repeat(2, minmax(0, 1fr)); // note: 0 must come first before 1fr in minmax()\r\n  column-gap: 12px;\r\n  row-gap: 12px;\r\n  @include spacing.padding($x: 16px);\r\n\r\n  .inBattle & {\r\n    grid-template-columns: minmax(0, 1fr);\r\n    row-gap: 12px;\r\n  }\r\n\r\n  .settingsGroupTitle {\r\n    grid-area: span 1 / span 2;\r\n    @include spacing.margin($top: 16px, $bottom: 6px);\r\n    @include spacing.padding($x: 0);\r\n    font-size: 12px;\r\n\r\n    .inBattle & {\r\n      grid-area: span 1 / span 1;\r\n      @include spacing.margin($left: -0.5px); // matches letter-spacing of .settingsGroupTitle\r\n      text-align: center;\r\n    }\r\n\r\n    .light & {\r\n      color: color.alpha(colors.$black, 0.64);\r\n    }\r\n\r\n    .dark & {\r\n      color: color.alpha(colors.$white, 0.64);\r\n    }\r\n  }\r\n\r\n  .field {\r\n    grid-area: span 1 / span 1;\r\n    align-self: center;\r\n  }\r\n\r\n  // fixes tooltips appearing in empty spaces, which could get annoying\r\n  // (otherwise, it'll extend like `width: 100%` !!)\r\n  .switchField {\r\n    width: fit-content;\r\n  }\r\n\r\n  .singleColumn {\r\n    grid-area: span 1 / span 2;\r\n  }\r\n}\r\n\r\n// this is basically a container for a pseudo-component frankensteined\r\n// from other components (namely the NHKO fields)\r\n// (should typically be applied with .field)\r\n.customField {\r\n  @include spacing.padding($x: 5px, $y: 2px);\r\n}\r\n\r\n// mimics the labels of form components\r\n.customFieldLabel {\r\n  font-weight: 500;\r\n  font-size: 12px;\r\n  user-select: none;\r\n\r\n  .inBattle & {\r\n    text-align: center;\r\n  }\r\n\r\n  &.top {\r\n    @include spacing.margin($bottom: 3px);\r\n  }\r\n\r\n  &.right {\r\n    @include spacing.margin($left: 10px);\r\n  }\r\n\r\n  &.bottom {\r\n    @include spacing.margin($top: 3px);\r\n  }\r\n\r\n  &.left {\r\n    @include spacing.margin($right: 10px);\r\n  }\r\n}\r\n\r\n.customFieldRow {\r\n  @include flex.row($align: center);\r\n  @include spacing.margin($top: 7px);\r\n\r\n  &.centered {\r\n    justify-content: center;\r\n  }\r\n\r\n  .customFieldInput:not(:last-child) {\r\n    @include spacing.margin($right: 5px);\r\n  }\r\n}\r\n\r\n.textField {\r\n  @include spacing.padding($x: 3px, $y: 5px);\r\n  font-size: 10px;\r\n\r\n  &.nhkoLabelField {\r\n    max-width: 75px;\r\n  }\r\n\r\n  &.nhkoColorField {\r\n    max-width: 70px;\r\n  }\r\n\r\n  .textFieldInput {\r\n    text-align: center;\r\n  }\r\n}\r\n\r\n.tooltipContent {\r\n  max-width: 248px;\r\n  font-size: 10px;\r\n  text-align: center;\r\n  line-height: 12px;\r\n  white-space: normal;\r\n  user-select: none;\r\n}\r\n\r\n// these are primarily used for the defaultAutoPreset Field in AutoFeaturesSettingsPane\r\n.strongText {\r\n  font-weight: 600;\r\n}\r\n\r\n.blueColor {\r\n  color: colors.$blue;\r\n}\r\n","////\r\n/// @group position\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:meta';\r\n@use 'functions/list';\r\n\r\n@mixin -position(\r\n  $position: relative,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('absolute' 'fixed' 'relative', $position) {\r\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\r\n  }\r\n\r\n  position: $position;\r\n\r\n  @if $top {\r\n    top: $top;\r\n  }\r\n\r\n  @if $right {\r\n    right: $right;\r\n  }\r\n\r\n  @if $bottom {\r\n    bottom: $bottom;\r\n  }\r\n\r\n  @if $left {\r\n    left: $left;\r\n  }\r\n}\r\n\r\n// translate\r\n\r\n@mixin translate(\r\n  $x: null,\r\n  $y: null,\r\n) {\r\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\r\n    @if $x and $x != 0 and $y and $y != 0 {\r\n      transform: translate($x, $y);\r\n    } @else if $x and $x != 0 {\r\n      transform: translateX($x);\r\n    } @else if $y and $y != 0 {\r\n      transform: translateY($y);\r\n    }\r\n  }\r\n}\r\n\r\n// unset all\r\n\r\n@mixin unset-all {\r\n  top: unset;\r\n  right: unset;\r\n  bottom: unset;\r\n  left: unset;\r\n}\r\n\r\n// absolute\r\n\r\n@mixin absolute(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -position(\r\n    $position: absolute,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin absolute-xy($x: null, $y: null) {\r\n  @include absolute($x: $x, $y: $y);\r\n}\r\n\r\n@mixin absolute-axis($horizontal: null, $vertical: null) {\r\n  @include absolute($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin absolute-all($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n@mixin absolute-square($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n@mixin absolute-fill {\r\n  @include absolute($all: 0);\r\n}\r\n\r\n@mixin absolute-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  $translate-x: if($x, -$x, null);\r\n  $translate-y: if($y, -$y, null);\r\n\r\n  @if $translate-x and unit($translate-x) != '%' { // e.g., px\r\n    $translate-x: 0;\r\n  }\r\n\r\n  @if $translate-y and unit($translate-y) != '%' {\r\n    $translate-y: 0;\r\n  }\r\n\r\n  @include absolute(\r\n    $top: if($y-prop == top, $y, null),\r\n    $right: if($x-prop == right, $x, null),\r\n    $bottom: if($y-prop == bottom, $y, null),\r\n    $left: if($x-prop == left, $x, null),\r\n  );\r\n\r\n  @include translate($x: $translate-x, $y: $translate-y);\r\n}\r\n\r\n@mixin absolute-center($x-prop: left, $y-prop: top) {\r\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\r\n}\r\n\r\n// fixed\r\n\r\n@mixin fixed(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -position(\r\n    $position: fixed,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin fixed-xy($x: null, $y: null) {\r\n  @include fixed($x: $x, $y: $y);\r\n}\r\n\r\n@mixin fixed-axis($horizontal: null, $vertical: null) {\r\n  @include fixed($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin fixed-all($margin) {\r\n  @include fixed($all: $margin);\r\n}\r\n\r\n@mixin fixed-square($margin) {\r\n  @include fixed($all: $margin);\r\n}\r\n\r\n@mixin fixed-fill {\r\n  @include fixed($all: 0);\r\n}\r\n\r\n@mixin fixed-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  $translate-x: if($x, -$x, null);\r\n  $translate-y: if($y, -$y, null);\r\n\r\n  @if $translate-x and unit($translate-x) != '%' {\r\n    $translate-x: 0;\r\n  }\r\n\r\n  @if $translate-y and unit($translate-y) != '%' {\r\n    $translate-y: 0;\r\n  }\r\n\r\n  @include fixed(\r\n    $top: if($y-prop == top, $y, null),\r\n    $right: if($x-prop == right, $x, null),\r\n    $bottom: if($y-prop == bottom, $y, null),\r\n    $left: if($x-prop == left, $x, null),\r\n  );\r\n\r\n  @include translate($x: $translate-x, $y: $translate-y);\r\n}\r\n\r\n@mixin fixed-center($x-prop: left, $y-prop: top) {\r\n  @include fixed-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\r\n}\r\n","////\r\n/// @group transition\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:list';\r\n@use 'sass:meta';\r\n@use 'config/animations';\r\n\r\n@mixin apply($props...) {\r\n  $transitions: ();\r\n\r\n  @for $i from 1 through list.length($props) {\r\n    $prop: list.nth($props, $i);\r\n\r\n    $name: $prop;\r\n    $duration: animations.$transition-duration;\r\n    $function: animations.$transition-function;\r\n\r\n    @if meta.type-of($prop) == 'list' and list.length($prop) > 1 {\r\n      $name: list.nth($prop, 1);\r\n\r\n      @if list.nth($prop, 2) {\r\n        $duration: list.nth($prop, 2);\r\n      }\r\n\r