nt: $justify;\r\n  }\r\n\r\n  @if $align and $align != stretch {\r\n    align-items: $align;\r\n  }\r\n\r\n  // @if $inline {\r\n  //   vertical-align: middle;\r\n  // }\r\n}\r\n\r\n// rows\r\n\r\n@mixin row($justify: null, $align: null, $inline: false) {\r\n  @include -flex(row, $justify, $align, $inline);\r\n}\r\n\r\n@mixin row-start($inline: false) {\r\n  @include row(flex-start, center, $inline);\r\n}\r\n\r\n@mixin row-center($inline: false) {\r\n  @include row(center, center, $inline);\r\n}\r\n\r\n@mixin row-end($inline: false) {\r\n  @include row(flex-end, center, $inline);\r\n}\r\n\r\n@mixin row-between($inline: false) {\r\n  @include row(space-between, center, $inline);\r\n}\r\n\r\n@mixin row-around($inline: false) {\r\n  @include row(space-around, center, $inline);\r\n}\r\n\r\n// columns\r\n\r\n@mixin column($justify: null, $align: null, $inline: false) {\r\n  @include -flex(column, $justify, $align, $inline);\r\n}\r\n\r\n@mixin column-start($inline: false) {\r\n  @include column(flex-start, center, $inline);\r\n}\r\n\r\n@mixin column-center($inline: false) {\r\n  @include column(center, center, $inline);\r\n}\r\n\r\n@mixin column-end($inline: false) {\r\n  @include column(flex-end, center, $inline);\r\n}\r\n\r\n@mixin column-between($inline: false) {\r\n  @include column(space-between, center, $inline);\r\n}\r\n\r\n@mixin column-around($inline: false) {\r\n  @include column(space-around, center, $inline);\r\n}\r\n","////\r\n/// @group font\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:meta';\r\n@use 'sass:map';\r\n\r\n@mixin apply($font, $overrides: null) {\r\n  $props: (\r\n    'font-family',\r\n    'font-stretch',\r\n    'font-weight',\r\n  );\r\n\r\n  @each $prop in $props {\r\n    $value: map.get($font, $prop);\r\n\r\n    @if meta.type-of($overrides) == map and map.has-key($overrides, $prop) {\r\n      $value: map.get($overrides, $prop);\r\n    }\r\n\r\n    @if $value {\r\n      #{$prop}: $value;\r\n    } @else {\r\n      @warn 'Font prop `#{$