$item, label, font-weight);\r\n  font-size: map.get($item, label, font-size);\r\n  letter-spacing: map.get($item, label, letter-spacing);\r\n  word-spacing: normal;\r\n  pointer-events: none;\r\n}\r\n\r\n.separator {\r\n  width: 100%;\r\n  height: map.get($separator, height);\r\n  @include spacing.margin($x: map.get($separator, margin-x), $y: map.get($separator, margin-y));\r\n  pointer-events: none;\r\n  @include transition.apply(background-color);\r\n\r\n  .light & {\r\n    background-color: map.get($separator, background-color, light);\r\n  }\r\n\r\n  .dark & {\r\n    background-color: map.get($separator, background-color, dark);\r\n  }\r\n}\r\n\r\n// the .container declaration is required\r\n// (you can't just have a top-level :global() since it's not \"pure\"; needs to contain a local class or ID)\r\n.container {\r\n  &:global(.react-contexify__will-leave--disabled) {\r\n    pointer-events: none;\r\n  }\r\n\r\n  // shows .react-contexify__submenu when using keyboard navigation\r\n  // (note that the .submenu class is a CSS module!)\r\n  .submenu:global(.react-contexify__submenu--is-open) > div:nth-of-type(2) {\r\n    opacity: 1;\r\n    pointer-events: initial;\r\n  }\r\n}\r\n\r\n// contexify animations\r\n.container {\r\n  @keyframes scale-in {\r\n    from {\r\n      opacity: 0;\r\n      transform: scale3d(0.3, 0.3, 0.3);\r\n    }\r\n\r\n    to {\r\n      opacity: 1;\r\n    }\r\n  }\r\n\r\n  &:global(.contexify_willEnter-scale) {\r\n    transform-origin: top left;\r\n    animation: scale-in 256ms ease;\r\n  }\r\n\r\n  @keyframes scale-out {\r\n    from {\r\n      opacity: 1;\r\n    }\r\n\r\n    to {\r\n      opacity: 0;\r\n      transform: scale3d(0.3, 0.3, 0.3);\r\n    }\r\n  }\r\n\r\n  // without `forwards`, the menu will flash w/ full opacity right at the end\r\n  &:global(.contexify_willLeave-scale) {\r\n    transform-origin: top left;\r\n    animation: scale-out 128ms ease forwards;\r\n  }\r\n}\r\n","////\r\n/// @group position\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:meta';\r\n@use 'functions/list';\r\n\r\n@mixin -position(\r\n  $position: relative,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('absolute' 'fixed' 'relative', $position) {\r\n    @error 'Invalid $position value passed to the -position() mixin: #{$position}';\r\n  }\r\n\r\n  position: $position;\r\n\r\n  @if $top {\r\n    top: $top;\r\n  }\r\n\r\n  @if $right {\r\n    right: $right;\r\n  }\r\n\r\n  @if $bottom {\r\n    bottom: $bottom;\r\n  }\r\n\r\n  @if $left {\r\n    left: $left;\r\n  }\r\n}\r\n\r\n// translate\r\n\r\n@mixin translate(\r\n  $x: null,\r\n  $y: null,\r\n) {\r\n  @if meta.type-of($x) == 'number' or meta.type-of($y) == 'number' {\r\n    @if $x and $x != 0 and $y and $y != 0 {\r\n      transform: translate($x, $y);\r\n    } @else if $x and $x != 0 {\r\n      transform: translateX($x);\r\n    } @else if $y and $y != 0 {\r\n      transform: translateY($y);\r\n    }\r\n  }\r\n}\r\n\r\n// unset all\r\n\r\n@mixin unset-all {\r\n  top: unset;\r\n  right: unset;\r\n  bottom: unset;\r\n  left: unset;\r\n}\r\n\r\n// absolute\r\n\r\n@mixin absolute(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -position(\r\n    $position: absolute,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin absolute-xy($x: null, $y: null) {\r\n  @include absolute($x: $x, $y: $y);\r\n}\r\n\r\n@mixin absolute-axis($horizontal: null, $vertical: null) {\r\n  @include absolute($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin absolute-all($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n@mixin absolute-square($margin) {\r\n  @include absolute($all: $margin);\r\n}\r\n\r\n@mixin absolute-fill {\r\n  @include absolute($all: 0);\r\n}\r\n\r\n@mixin absolute-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  $translate-x: if($x, -$x, null);\r\n  $translate-y: if($y, -$y, null);\r\n\r\n  @if $translate-x and unit($translate-x) != '%' { // e.g., px\r\n    $translate-x: 0;\r\n  }\r\n\r\n  @if $translate-y and unit($translate-y) != '%' {\r\n    $translate-y: 0;\r\n  }\r\n\r\n  @include absolute(\r\n    $top: if($y-prop == top, $y, null),\r\n    $right: if($x-prop == right, $x, null),\r\n    $bottom: if($y-prop == bottom, $y, null),\r\n    $left: if($x-prop == left, $x, null),\r\n  );\r\n\r\n  @include translate($x: $translate-x, $y: $translate-y);\r\n}\r\n\r\n@mixin absolute-center($x-prop: left, $y-prop: top) {\r\n  @include absolute-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\r\n}\r\n\r\n// fixed\r\n\r\n@mixin fixed(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -position(\r\n    $position: fixed,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin fixed-xy($x: null, $y: null) {\r\n  @include fixed($x: $x, $y: $y);\r\n}\r\n\r\n@mixin fixed-axis($horizontal: null, $vertical: null) {\r\n  @include fixed($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin fixed-all($margin) {\r\n  @include fixed($all: $margin);\r\n}\r\n\r\n@mixin fixed-square($margin) {\r\n  @include fixed($all: $margin);\r\n}\r\n\r\n@mixin fixed-fill {\r\n  @include fixed($all: 0);\r\n}\r\n\r\n@mixin fixed-anchor(\r\n  $x: null,\r\n  $y: null,\r\n  $x-prop: left,\r\n  $y-prop: top,\r\n) {\r\n  $translate-x: if($x, -$x, null);\r\n  $translate-y: if($y, -$y, null);\r\n\r\n  @if $translate-x and unit($translate-x) != '%' {\r\n    $translate-x: 0;\r\n  }\r\n\r\n  @if $translate-y and unit($translate-y) != '%' {\r\n    $translate-y: 0;\r\n  }\r\n\r\n  @include fixed(\r\n    $top: if($y-prop == top, $y, null),\r\n    $right: if($x-prop == right, $x, null),\r\n    $bottom: if($y-prop == bottom, $y, null),\r\n    $left: if($x-prop == left, $x, null),\r\n  );\r\n\r\n  @include translate($x: $translate-x, $y: $translate-y);\r\n}\r\n\r\n@mixin fixed-center($x-prop: left, $y-prop: top) {\r\n  @include fixed-anchor($x: 50%, $y: 50%, $x-prop: $x-prop, $y-prop: $y-prop);\r\n}\r\n","////\r\n/// @group spacing\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'functions/list';\r\n\r\n@mixin -spacing(\r\n  $prop,\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n) {\r\n  @if not list.includes('margin' 'padding', $prop) {\r\n    @error 'Invalid $prop value passed to the -spacing() mixin: #{$prop}';\r\n  }\r\n\r\n  @if $top and $right and $bottom and $left { // all directions specified\r\n    @if $right == $left {\r\n      @if $top == $bottom {\r\n        @if $top == $right { // $top (== $bottom) == $right (== $left)\r\n          #{$prop}: $top;\r\n        } @else { // $top (== $bottom) != $right (== $left)\r\n          #{$prop}: $top $right;\r\n        }\r\n      } @else { // $top != $bottom, but $right == $left\r\n        #{$prop}: $top $right $bottom;\r\n      }\r\n    } @else { // $right != $left\r\n      #{$prop}: $top $right $bottom $left;\r\n    }\r\n  } @else { // not all directions specified\r\n    @if $top {\r\n      #{$prop}-top: $top;\r\n    }\r\n\r\n    @if $right {\r\n      #{$prop}-right: $right;\r\n    }\r\n\r\n    @if $bottom {\r\n      #{$prop}-bottom: $bottom;\r\n    }\r\n\r\n    @if $left {\r\n      #{$prop}-left: $left;\r\n    }\r\n  }\r\n}\r\n\r\n// margin\r\n\r\n@mixin margin(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: margin,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin margin-xy($x: null, $y: null) {\r\n  @include margin($x: $x, $y: $y);\r\n}\r\n\r\n@mixin margin-axis($horizontal: null, $vertical: null) {\r\n  @include margin($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin margin-center($vertical: null) {\r\n  @include margin($x: auto, $y: $vertical);\r\n}\r\n\r\n@mixin margin-middle($horizontal: null) {\r\n  @include margin($x: $horizontal, $y: auto);\r\n}\r\n\r\n@mixin margin-all($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-square($margin) {\r\n  @include margin($all: $margin);\r\n}\r\n\r\n@mixin margin-auto {\r\n  @include margin($all: auto);\r\n}\r\n\r\n@mixin margin-none {\r\n  @include margin($all: 0);\r\n}\r\n\r\n// padding\r\n\r\n@mixin padding(\r\n  $top: null,\r\n  $right: null,\r\n  $bottom: null,\r\n  $left: null,\r\n  $x: null,\r\n  $y: null,\r\n  $all: null,\r\n) {\r\n  @include -spacing(\r\n    $prop: padding,\r\n    $top: if($top, $top, if($y, $y, $all)),\r\n    $right: if($right, $right, if($x, $x, $all)),\r\n    $bottom: if($bottom, $bottom, if($y, $y, $all)),\r\n    $left: if($left, $left, if($x, $x, $all)),\r\n  );\r\n}\r\n\r\n@mixin padding-xy($x: null, $y: null) {\r\n  @include padding($x: $x, $y: $y);\r\n}\r\n\r\n@mixin padding-axis($horizontal: null, $vertical: null) {\r\n  @include padding($x: $horizontal, $y: $vertical);\r\n}\r\n\r\n@mixin padding-all($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-square($padding) {\r\n  @include padding($all: $padding);\r\n}\r\n\r\n@mixin padding-none {\r\n  @include padding($all: 0);\r\n}\r\n","////\r\n/// @group font\r\n/// @author Keith Choison\r\n////\r\n\r\n@use 'sass:meta';\r\n@use 'sass:map';\r\n\r\n@mixin apply($font, $overrides: null) {\r\n  $props: (\r\n    'font-family',\r\n    'font-stretch',\r\n    'font-weight',\r\n  );\r\n\r\n  @each $prop i